CREATE TABLE transport_bookings(`id` bigint  UNSIGNED PRIMARY KEY AUTO_INCREMENT,`created_at` timestamp  DEFAULT CURRENT_TIMESTAMP NOT NULL,`updated_at` timestamp  DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP NOT NULL,`enable` TINYINT(1)  NOT NULL  DEFAULT 1 ,`transaction_id` bigint  NOT NULL,`provider_id` bigint  NOT NULL,`requester_id` bigint  NOT NULL COMMENT 'User who requested transport (buyer or seller)',`pickup_address` text  NOT NULL,`pickup_latitude` DECIMAL(10,8)  NULL,`pickup_longitude` DECIMAL(11,8)  NULL,`delivery_address` text  NOT NULL,`delivery_latitude` DECIMAL(10,8)  NULL,`delivery_longitude` DECIMAL(11,8)  NULL,`distance_km` DECIMAL(10,2)  NOT NULL COMMENT 'Calculated distance in kilometers',`livestock_type` varchar(100)  NOT NULL COMMENT 'cattle, goat, sheep, poultry, buffalo',`livestock_count` INT  NOT NULL,`animal_value` DECIMAL(12,2)  NOT NULL COMMENT 'Total value of animals for insurance',`transport_cost` DECIMAL(10,2)  NOT NULL COMMENT 'Base transport cost in INR',`insurance_opted` TINYINT(1)  DEFAULT 0,`insurance_cost` DECIMAL(10,2)  NULL COMMENT 'Insurance cost in INR',`total_cost` DECIMAL(10,2)  NOT NULL COMMENT 'Total cost including insurance',`scheduled_pickup_date` timestamp  NOT NULL,`estimated_delivery_date` timestamp  NOT NULL,`actual_pickup_date` timestamp  NULL,`actual_delivery_date` timestamp  NULL,`status` varchar(50)  DEFAULT 'pending' COMMENT 'pending, confirmed, in_transit, delivered, cancelled',`tracking_updates` text  NULL COMMENT 'JSON array of status updates with timestamps',`special_instructions` text  NULL,`rating` INT  NULL COMMENT 'Rating 1-5 after delivery',`review` text  NULL,`reviewed_at` timestamp  NULL,`cancelled_at` timestamp  NULL,`cancellation_reason` text  NULL)ENGINE = InnoDB AUTO_INCREMENT = 1 DEFAULT CHARSET = utf8;